('이소미','시간 계산','시계에서 가장 가늘고 끝에 동그라미가 있는 바늘(초바늘)이 가리키는 시각은 몇 초인가요?'),
('이소미','시간 계산','어느 해 3월의 달력입니다. 색칠한 날(3월 5일부터 3월 18일까지) 동안 수영을 배웠다면, 수영을 배운 기간은 몇 주일인가요?'),
('이소미','시간 계산','어느 해 5월의 달력입니다. 이 달의 셋째 금요일은 며칠인가요?'),
('이소미','시간 계산','초바늘이 2바퀴 도는 데 걸리는 시간은 몇 초인가요?'),
